<?php get_header();$title=get_theme_mod('bsktv_hero_title','高雄商務KTV／酒店資訊');$text=get_theme_mod('bsktv_hero_text','一篇文章就是一家店，完整整理店家介紹、消費方式與實用資訊。'); ?><main><section class="hero"><div class="container"><h1><?php echo esc_html($title); ?></h1><p><?php echo esc_html($text); ?></p><form class="search-box" action="<?php echo esc_url(home_url('/')); ?>" method="get"><input name="s" placeholder="搜尋酒店、KTV、店家名稱…"><button class="btn">搜尋店家</button></form></div></section><section class="section"><div class="container"><h2 class="section-title">最新酒店</h2><div class="store-grid"><?php $q=new WP_Query(array('post_type'=>'post','post_status'=>'publish','posts_per_page'=>9));while($q->have_posts()):$q->the_post();?><article class="store-card"><a href="<?php the_permalink(); ?>"><div class="store-card-image"><?php if(has_post_thumbnail())the_post_thumbnail('large'); ?></div><div class="store-card-body"><h3><?php the_title(); ?></h3><div class="store-meta"><?php echo esc_html(bsktv_meta('bsktv_address')); ?></div></div></a></article><?php endwhile;wp_reset_postdata(); ?></div></div></section></main><?php get_footer(); ?>